    describe('Label Cache', () => {
        test('should generate label cache with correct structure', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-def-with-variables.now.ts')

            const flowRecord = merged['sys_hub_flow'][0]
            expect(flowRecord.label_cache).toBeDefined()

            const labelCache = JSON.parse(flowRecord.label_cache)
            expect(Array.isArray(labelCache)).toBe(true)

            // Each entry should have required fields
            if (labelCache.length > 0) {
                labelCache.forEach((pill: any) => {
                    expect(pill).toHaveProperty('name')
                    expect(pill).toHaveProperty('label')
                    expect(pill).toHaveProperty('usedInstances')
                    expect(pill.name).toMatch(/^(flow_variable|subflow|trigger)\./)
                })
            }
        })

        test('should clear instance attributes after label cache extraction', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-def-with-variables.now.ts')

            // All action instances should have empty attributes
            if (merged['sys_hub_action_instance_v2']) {
                merged['sys_hub_action_instance_v2'].forEach((instance: any) => {
                    expect(instance.attributes).toBe('')
                })
            }

            // All subflow instances should have empty attributes
            if (merged['sys_hub_sub_flow_instance_v2']) {
                merged['sys_hub_sub_flow_instance_v2'].forEach((instance: any) => {
                    expect(instance.attributes).toBe('')
                })
            }
        })

        test('should generate proper labels with arrow separator', async () => {
            const merged = await getMergedRecordUpdates(ctx.createProject(), 'flow-def-with-variables.now.ts')

            const flowRecord = merged['sys_hub_flow'][0]
            const labelCache = JSON.parse(flowRecord.label_cache)

            labelCache.forEach((pill: any) => {
                if (pill.name.startsWith('flow_variable.')) {
                    expect(pill.label).toContain('➛')
                    expect(pill.label).toMatch(/^Flow Variables➛/)
                }
            })
        })
    })
